
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_mgga_xc_r2scan50_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_xc_r2scan50", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-2.468798224749238e+00, -2.419308757941087e+00, -2.349937814477209e+00, -2.253790178961304e+00, -2.122665900592198e+00, -1.947909250692319e+00, -1.722457551384124e+00, -1.444541506097945e+00, -1.122613621870431e+00, -7.762130852135866e-01, -4.556764004211989e-01, -3.565372686688975e-01, -3.529337967801366e-01, -2.900721626557976e-01, -2.004084924892206e-01, -1.127415733380414e-01, -4.662780079495586e-02, -1.316023650215588e-02, -1.956761265664914e-03, -9.606881400092796e-05]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


